local config = {
  ui_story_5034_50340000_1_dialog_content = "<color=#e8d9bb>Crash!</color>",
  ui_story_5034_50340000_2_dialog_content = "Oh no! Are you okay?",
  ui_story_5034_50340000_3_dialog_content = "I-I'm fine...",
  ui_story_5034_50340000_4_dialog_content = "Huh? It's you, Mr. Navigator!",
  ui_story_5034_50340000_5_dialog_content = "Oh, hello, <color=#FFB400>Schewe</color>.",
  ui_story_5034_50340000_6_dialog_content = "You know you can just call me by my name, right? Like how Nekoyashiki and the others do.",
  ui_story_5034_50340000_7_dialog_content = "What? No way!",
  ui_story_5034_50340000_8_dialog_content = "You're older than me, and I have to respect my seniors!",
  ui_story_5034_50340000_9_dialog_content = "Er... Okay, then.",
  ui_story_5034_50340000_10_dialog_content = "What did you think of the candy? Did it taste good?",
  ui_story_5034_50340000_11_dialog_content = "O-Of course! It was absolutely delicious!",
  ui_story_5034_50340000_12_dialog_content = "It's our favorite candy! Thank you, Mr. Navigator!",
  ui_story_5034_50340000_13_dialog_content = "Schewe's lying! He didn't eat it at all!",
  ui_story_5034_50340000_14_dialog_content = "Latan! Mr. Navigator and I are talking, go away!",
  ui_story_5034_50340000_15_dialog_content = "But you lied, Schewe! You gave the candy to me...",
  ui_story_5034_50340000_16_dialog_content = "Remember what Pollux told us? We shouldn't lie to people that are kind to us!",
  ui_story_5034_50340000_17_dialog_content = "I didn't mean to lie, now butt out!",
  ui_story_5034_50340000_18_dialog_content = "Schewe... Did you ask me for that candy so you could make Latan feel better?",
  ui_story_5034_50340000_19_dialog_content = "Guess there's no getting past you, Mr. Navigator. I'm sorry, I shouldn't have lied in the first place.",
  ui_story_5034_50340000_20_dialog_content = "Mr. Navigator? I really want Schewe to have some candy, too.",
  ui_story_5034_50340000_21_dialog_content = "If I knew there was only one piece, I wouldn't have eaten it all in one bite...",
  ui_story_5034_50340000_22_dialog_content = "Don't be a bother, Latan. I'm fine without.",
  ui_story_5034_50340000_23_dialog_content = "Just seeing you back to your old self makes me feel happier than eating any candy!",
  ui_story_5034_50340000_24_dialog_content = "Alright, kiddos. That'll do for now.",
  ui_story_5034_50340000_25_dialog_content = "It's just some candy, you know? Buying candy is no big deal for someone grown up like me.",
  ui_story_5034_50340000_26_dialog_content = "But only Nekoyashiki has that kind of candy... We can't find it in Euphoria at all.",
  ui_story_5034_50340000_27_dialog_content = "If Nekoyashiki can get his hands on it somehow, then why can't I? Give me some credit, guys!",
  ui_story_5034_50340000_28_dialog_content = "Just wait, I'll bring you back so much candy that you won't be able to finish it all!",
  ui_story_5034_50340000_29_dialog_content = "Yay! You're the best, Mr. Navigator! No one is nicer than you!",
  ui_story_5034_50340000_30_dialog_content = "Hey, Latan, don't say that...",
  ui_story_5034_50340000_31_dialog_content = "What if Mr. Navigator isn't able to find the candy?",
  ui_story_5034_50340000_32_dialog_content = "Thanks for the vote of confidence, Schewe...",
  ui_story_5034_50340000_33_dialog_content = "Anyway, grown-ups should always keep their promises to children. You two just wait here for me, and I'll be back soon.",
  ui_story_5034_50340000_34_dialog_content = "(Now where should I go to look for that candy...?)",
  ui_story_5034_50340000_35_dialog_content = "(Oh, yeah! I bet she'd have some idea!)",
  ui_story_5034_50340000_36_dialog_content = "Hmm? Already feeling rested, I see?",
  ui_story_5034_50340000_37_dialog_content = "Definitely! I feel perfectly fine now.",
  ui_story_5034_50340000_38_dialog_content = "By the way, Pollux... There's something I'd like to ask you.",
  ui_story_5034_50340000_39_dialog_content = "Do you know where I can find more of that candy that the children like?",
  ui_story_5034_50340000_40_dialog_content = "You're talking about the candy that Nekoyashiki usually brings along, yes?",
  ui_story_5034_50340000_41_dialog_content = "I haven't seen it anywhere in Euphoria, which means he must be bringing it from someplace else.",
  ui_story_5034_50340000_42_dialog_content = "But why don't you go and ask him yourself? I don't think he's left yet.",
  ui_story_5034_50340000_43_option_content = "Not a chance!",
  ui_story_5034_50340000_44_dialog_content = "Besides, it's just candy. If he can get ahold of it, then so can I.",
  ui_story_5034_50340000_45_dialog_content = "As long as he doesn't make it himself, I'm sure I can find a way to buy some!",
  ui_story_5034_50340000_46_option_content = "Looks like I have no choice but to ask him...",
  ui_story_5034_50340000_47_dialog_content = "Is there really no other way...?",
  ui_story_5034_50340000_48_dialog_content = "Thank you, Pollux.",
  ui_story_5034_50340000_49_dialog_content = "Wait, PlayerName. I just remembered a certain shop in town that has been in business for a really long time.",
  ui_story_5034_50340000_50_dialog_content = "The shopkeeper is pretty business-savvy and brings in all kinds of exotic goods to sell here in Euphoria.",
  ui_story_5034_50340000_51_dialog_content = "You might want to try your luck there first.",
  ui_story_5034_50340000_52_dialog_content = "Got it! Thanks again, Pollux!",
  ui_story_5034_50340000_53_dialog_content = "Hey! I still haven't told you where the shop is!",
  ui_story_5034_50340000_54_dialog_content = "Always in such a hurry...",
  ui_story_5034_50340000_55_dialog_content = "Corax! Where are you, Corax?",
  ui_story_5034_50340000_56_dialog_content = "Right behind you... What's with all the shouting?",
  ui_story_5034_50340000_57_dialog_content = "Ahhh! Don't sneak up on me like that!",
  ui_story_5034_50340000_58_dialog_content = "Anyway, you got a minute, Corax?",
  ui_story_5034_50340000_59_dialog_content = "Why do you ask?",
  ui_story_5034_50340000_60_dialog_content = "I want to buy some candy, but the shop that sells it is in the town, and I don't want to go alone...",
  ui_story_5034_50340000_61_dialog_content = "Can't help you. I'm going somewhere nice and vacant to feed the birds.",
  ui_story_5034_50340000_62_dialog_content = "Huh? Am I really less important than a couple of birds?",
  ui_story_5034_50340000_63_dialog_content = "Oh hey, Nekoyashiki. You're just in time.",
  ui_story_5034_50340000_64_dialog_content = "PlayerName wants to go into town to buy some candy. Go with him, would you? I don't have time for it.",
  ui_story_5034_50340000_65_dialog_content = "Corax...",
  ui_story_5034_50340000_66_dialog_content = "Ah... Candy, you say?",
  ui_story_5034_50340000_67_dialog_content = "So that candy I gave you before... You ate it yourself instead of giving it to the kids, didn't you?",
  ui_story_5034_50340000_68_dialog_content = "Didn't know that was the kind of person you were, PlayerName...",
  ui_story_5034_50340000_69_dialog_content = "Don't let your imagination run wild! I just wanted to buy more for the kids, that's all.",
  ui_story_5034_50340000_70_dialog_content = "But since you're already here, it saves me the trouble of going into town.",
  ui_story_5034_50340000_71_dialog_content = "If you have any more of that candy, why don't you sell it all to me?",
  ui_story_5034_50340000_72_dialog_content = "I would love to help you look cool in front of the kids, PlayerName...",
  ui_story_5034_50340000_73_dialog_content = "But unfortunately, I've already given out or eaten the rest of the candy.",
  ui_story_5034_50340000_74_dialog_content = "That piece I gave you happened to be the last of it.",
  ui_story_5034_50340000_75_dialog_content = "Really... Looks like I'll have to try my luck at that shop, after all...",
  ui_story_5034_50340000_76_dialog_content = "\"That shop\"?",
  ui_story_5034_50340000_77_dialog_content = "I had no idea there was a shop in Euphoria that stocked this kind of candy... Now I'm really curious to see it myself.",
  ui_story_5034_50340000_78_dialog_content = "I asked Pollux, and she told me about a shop in town that imports all kinds of exotic goods. I'm going to see if I can find it there.",
  ui_story_5034_50340000_79_dialog_content = "<size=30>Ah... that shop...</size>",
  ui_story_5034_50340000_80_dialog_content = "Crap, wait a minute... I totally forgot to ask Pollux where it is.",
  ui_story_5034_50340000_81_dialog_content = "I wonder if she's still at the entrance...",
  ui_story_5034_50340000_82_dialog_content = "I know where it is. Come on, I'll take you there.",
  ui_story_5034_50340000_83_dialog_content = "What...? You're going with me?",
  ui_story_5034_50340000_84_dialog_content = "I'm just curious to see if the shopkeeper has what it takes to get ahold of this kind of candy, that's all.",
  ui_story_5034_50340000_85_dialog_content = "We just happen to be going in the same direction.",
  ui_story_5034_50340000_86_dialog_content = "Now hurry up, or I'm leaving on my own.",
  ui_story_5034_50340000_87_dialog_content = "Hey! Wait for me!",
  ui_story_5034_50340101_1_dialog_content = "We should be getting there soon, right? It feels like we've been walking forever...",
  ui_story_5034_50340101_2_dialog_content = "Yeah... If I'm not mistaken, then this should be the shop that Pollux was talking about.",
  ui_story_5034_50340101_3_dialog_content = "Come on, let's go inside and take a look around.",
  ui_story_5034_50340101_4_dialog_content = "Well, if it isn't Nekoyashiki... To what do I owe the pleasure of such a rare customer?",
  ui_story_5034_50340101_5_dialog_content = "I never thought a humble shop like mine could carry anything of interest for someone like you.",
  ui_story_5034_50340101_6_dialog_content = "Oh, don't mind me, I'm just taking a look around... He, on the other hand, is interested in buying something.",
  ui_story_5034_50340101_7_dialog_content = "Pardon me, but do you happen to sell any candy here?",
  ui_story_5034_50340101_8_dialog_content = "You'll have to search for it yourself. Also, we don't sell anything on credit, so don't bother asking.",
  ui_story_5034_50340101_9_dialog_content = "Someone got up on the wrong side of bed...",
  ui_story_5034_50340101_10_dialog_content = "Never mind, I don't mind looking on my own.",
  ui_story_5034_50340101_11_dialog_content = "Ah! Found it! I can't believe it's actually in stock here!",
  ui_story_5034_50340101_12_dialog_content = "Hm? Let me see that...",
  ui_story_5034_50340101_13_dialog_content = "Oh? Say, shopkeeper... Where exactly did you import this from?",
  ui_story_5034_50340101_14_dialog_content = "Trying to squeeze me out of business, eh? You already have plenty of channels for your goods, so there's no need for me to tell you about mine, thank you very much.",
  ui_story_5034_50340101_15_dialog_content = "Running even a small shop like mine isn't easy, you know? Try to think of the little people once in a while, \"Master\" Nekoyashiki.",
  ui_story_5034_50340101_16_dialog_content = "If business is so hard, why would you import an unpopular candy like this? Aren't you worried about losing your profits?",
  ui_story_5034_50340101_17_dialog_content = "I noticed that the children here are fond of this candy. If I can't sell them, I'll just give it to the kids.",
  ui_story_5034_50340101_18_dialog_content = "Ah, I see...",
  ui_story_5034_50340101_19_dialog_content = "Would you look at that? Guess you're not the only one who carries that kind of candy now, huh?",
  ui_story_5034_50340101_20_dialog_content = "It appears so... Well, congratulations are in order, I suppose.",
  ui_story_5034_50340101_21_dialog_content = "I'll take it all, sir!",
  ui_story_5034_50340101_22_dialog_content = "Splendid! Now then, they're 3,000 Nightium per bag, for a total of...",
  ui_story_5034_50340101_23_dialog_content = "Wait a second! Did you say 3,000 Nightium per bag?!",
  ui_story_5034_50340101_24_dialog_content = "*Snickering*",
  ui_story_5034_50340101_25_dialog_content = "Why yes, that's what I said. Each bag of this particular candy costs 3,000 Nightium.",
  ui_story_5034_50340101_26_dialog_content = "But if you buy out all my stock, I'll throw in a large tote bag for you to carry them home.",
  ui_story_5034_50340101_27_dialog_content = "But how could a single bag of candy cost 3,000 Nightium, to begin with?",
  ui_story_5034_50340101_28_dialog_content = "Nekoyashiki, how rich are you?!",
  ui_story_5034_50340101_29_dialog_content = "I never said I bought my candy here.",
  ui_story_5034_50340101_30_dialog_content = "So what you're saying... is that this guy is ripping me off, right?",
  ui_story_5034_50340101_31_dialog_content = "Euphoria doesn't have the means to produce candy, among other things. Most products are imported here through established trade routes.",
  ui_story_5034_50340101_32_dialog_content = "As a result, most things you find for sale here are more expensive than in other places.",
  ui_story_5034_50340101_33_dialog_content = "Are you telling me 3,000 Nightium for a measly bag of candy is acceptable to you then?!",
  ui_story_5034_50340101_34_dialog_content = "That's not what I said. I'm simply giving you some background information so you'll feel better when you're making your purchases.",
  ui_story_5034_50340101_35_dialog_content = "<size=45>That doesn't help at all.</size>",
  ui_story_5034_50340101_36_dialog_content = "You're more than welcome to buy individual bags of candy, if you'd like? Granted, the tote bag will be out of the question...",
  ui_story_5034_50340101_37_dialog_content = "(Guess I don't have a choice. I promised the kids after all... 3,000 Nightium a bag, I should be able to afford at least one... Right?)",
  ui_story_5034_50340101_38_dialog_content = "I... I only have 150 Nightium on me.",
  ui_story_5034_50340101_39_dialog_content = "Don't look at me, I bring my head when I leave the house, not my money.",
  ui_story_5034_50340101_40_dialog_content = "If only we were in Umbraton... I could get at least five bags of candy for 150 Nightium!",
  ui_story_5034_50340101_41_dialog_content = "No one here does anything about these exorbitant prices?",
  ui_story_5034_50340101_42_dialog_content = "But we're not in Umbraton, are we? We're in Euphoria, so you have to play by Euphoria's rules.",
  ui_story_5034_50340101_43_dialog_content = "And lest you forget, my friend, we don't sell anything on credit in this shop.",
  ui_story_5034_50340101_44_dialog_content = "If you're not buying anything, I'm returning this stuff to the shelves.",
  ui_story_5034_50340101_45_dialog_content = "(If I don't find a way to bring back this candy, Schewe and Latan will be so disappointed.)",
  ui_story_5034_50340101_46_dialog_content = "(And after everything I said, too...)",
  ui_story_5034_50340101_47_dialog_content = "I would like to purchase a bag, sir... But I really don't have enough money on me.",
  ui_story_5034_50340101_48_dialog_content = "Maybe I can trade something for a bag?",
  ui_story_5034_50340101_49_dialog_content = "I see... Well, I wouldn't want to turn down a friend of Nekoyashiki's so rudely.",
  ui_story_5034_50340101_50_dialog_content = "How's this? Why don't you stay awhile and work for me, and I'll give you that bag of candy as payment for your help? Does that sound fair?",
  ui_story_5034_50340101_51_dialog_content = "Sounds like a deal! So what exactly do you need me to do?",
  ui_story_5034_50340101_52_dialog_content = "I can't say I have much work experience, but I promise I'm one of the best in Astra.",
  ui_story_5034_50340101_53_dialog_content = "I should get going now. Best of luck, <color=#FFB400>part-timer</color>.",
  ui_story_5034_50340102_1_dialog_content = "(By the time I finally looked at the clock, an entire morning had nearly passed.)",
  ui_story_5034_50340102_2_dialog_content = "(Stocking and organizing shelves, sweeping the shop... He even wanted me to lure in customers.)",
  ui_story_5034_50340102_3_dialog_content = "(But who would even shop at a store with such insane prices?)",
  ui_story_5034_50340102_4_dialog_content = "Well, young man?",
  ui_story_5034_50340102_5_dialog_content = "Now you know how hard it is to run a shop in Euphoria.",
  ui_story_5034_50340102_6_dialog_content = "Even so, I wouldn't want to make things difficult for a friend of Nekoyashiki's...",
  ui_story_5034_50340102_7_dialog_content = "(Are you kidding me? I'm pretty sure you're doing this PRECISELY because I know him!)",
  ui_story_5034_50340102_8_dialog_content = "(It goes without saying, but I'm never coming back to this shop ever again!)",
  ui_story_5034_50340102_9_dialog_content = "Here you are, then, one bag of candy as payment for your hard work.",
  ui_story_5034_50340102_10_dialog_content = "I'm not sure if I should thank you or not...",
  ui_story_5034_50340102_11_dialog_content = "No thanks are necessary... But do try to remember to bring more money next time.",
  ui_story_5034_50340102_12_dialog_content = "Oh, you don't have to worry about that... there definitely won't be a next time!",
  ui_story_5034_50340102_13_dialog_content = "In any case, at least I got the candy.",
  ui_story_5034_50340102_14_dialog_content = "It's just a single bag, but I got it. Now Schewe can enjoy some too!",
  ui_story_5034_50340102_15_dialog_content = "Hmm? Wait a minute, there's something printed on the bag...",
  ui_story_5034_50340102_16_dialog_content = "\"Produced by Far Eastern Specialties in Umbraton...\"",
  ui_story_5034_50340102_17_dialog_content = "\"Suggested Retail Price: 30 Nightium...\"",
  ui_story_5034_50340102_18_dialog_content = "<size=45>What?!</size>",
  ui_story_5034_50340102_19_dialog_content = "I slaved away my entire morning to afford a 3,000 Nightium bag of candy, but after all of that...",
  ui_story_5034_50340102_20_dialog_content = "<size=45>It was just cheap Umbraton candy all along?!</size>",
  ui_story_5034_50340102_21_dialog_content = "Would you look at that? Guess you're not the only one who carries that kind of candy now, huh?",
  ui_story_5034_50340102_22_dialog_content = "It appears so... Well, congratulations are in order, I suppose.",
  ui_story_5034_50340102_23_dialog_content = "He knew! He knew, yet he didn't bother telling me!",
  ui_story_5034_50340102_24_dialog_content = "<color=#e8d9bb>*Grumbling*</color>",
  ui_story_5034_50340102_25_dialog_content = "Ugh... I'm starving after all that hard work...",
  ui_story_5034_50340102_26_dialog_content = "It's almost noon. If I hurry back, I should be able to make it in time for lunch with the kids.",
  ui_story_5034_50340102_27_dialog_content = "I'll let that crooked shopkeeper off the hook for now... Delivering this candy to the kids is way more important right now.",
  ui_story_5034_50340102_28_dialog_content = "But mark my words, the next time I see him... I'll give him a little lesson on fair trade!",
  ui_story_5034_50340102_29_dialog_content = "Look, Schewe! Mr. Navigator really managed to find some of that candy!",
  ui_story_5034_50340102_30_dialog_content = "You'll be able to try some too!",
  ui_story_5034_50340102_31_dialog_content = "But he worked hard all morning for that candy...",
  ui_story_5034_50340102_32_dialog_content = "That's true... We followed Mr. Navigator because we wanted to see where he got the candy.",
  ui_story_5034_50340102_33_dialog_content = "He said he was going to buy us lots, too...",
  ui_story_5034_50340102_34_dialog_content = "I knew he didn't really mean it.",
  ui_story_5034_50340102_35_dialog_content = "But if only we hadn't seemed so desperate to eat the candy...",
  ui_story_5034_50340102_36_dialog_content = "He wouldn't have had to work for that mean shopkeeper just to buy it for us.",
  ui_story_5034_50340102_37_dialog_content = "I was wrong, Latan... I don't deserve to eat the candy...",
  ui_story_5034_50340102_38_dialog_content = "Schewe...",
  ui_story_5034_50340102_39_dialog_content = "Wait! I have an idea!",
  ui_story_5034_50340102_40_dialog_content = "An idea...?",
  ui_story_5034_50340102_41_dialog_content = "If Mr. Navigator was able to work in that shop, then we can too!",
  ui_story_5034_50340102_42_dialog_content = "You mean we can work for the candy too?",
  ui_story_5034_50340102_43_dialog_content = "That's right! That way, Mr. Navigator won't think we're just a couple of selfish kids!",
  ui_story_5034_50340102_44_dialog_content = "We can't just stay here and wait for him to bring candy for us.",
  ui_story_5034_50340102_45_dialog_content = "He deserves to enjoy the fruits of our hard work, too!",
  ui_story_5034_50340102_46_dialog_content = "And with the two of us, we should be able to earn two bags instead of one! But what should we do with the second bag?",
  ui_story_5034_50340102_47_dialog_content = "Why not give it to Pollux as a gift? She works hard to take care of us, too... We should show her our gratitude!",
  ui_story_5034_50340102_48_dialog_content = "Then it's settled! As for that candy-hater, Casta... Should we use our <color=#FFB400>usual trick</color>?",
  ui_story_5034_50340102_49_dialog_content = "Well, this won't be easy, Latan.",
  ui_story_5034_50340102_50_dialog_content = "I know! Just leave it to me!",
  ui_story_5034_50340201_1_dialog_content = "Oh, you're back.",
  ui_story_5034_50340201_2_dialog_content = "I thought you went out just to get candy? Why are you so sweaty?",
  ui_story_5034_50340201_3_dialog_content = "\"Just to get candy,\" my ass...",
  ui_story_5034_50340201_4_dialog_content = "Have you seen Nekoyashiki? I need to \"thank\" him properly for helping me out.",
  ui_story_5034_50340201_5_dialog_content = "I haven't seen him around here. Didn't you two leave together?",
  ui_story_5034_50340201_6_dialog_content = "<color=#e8d9bb>*Grumbling*</color>",
  ui_story_5034_50340201_7_dialog_content = "Ah... So hungry... Guess I'll leave him be for now.",
  ui_story_5034_50340201_8_dialog_content = "Is lunch ready yet? What are we having today?",
  ui_story_5034_50340201_9_dialog_content = "Sorry, but everyone finished eating lunch a while ago.",
  ui_story_5034_50340201_10_dialog_content = "What?! And nobody thought to leave some for me?!",
  ui_story_5034_50340201_11_dialog_content = "You have a bag of candy in your hand, don't you? Just eat a few pieces, and it'll hold you over until dinner.",
  ui_story_5034_50340201_12_dialog_content = "No can do, this candy is for Schewe and Latan, as well as the other kids!",
  ui_story_5034_50340201_13_dialog_content = "You have no idea what I went through for this bag of candy...",
  ui_story_5034_50340201_14_dialog_content = "Speaking of which... where are Schewe and Latan, anyway?",
  ui_story_5034_50340201_15_dialog_content = "Do you know where those two are, Corax?",
  ui_story_5034_50340201_16_dialog_content = "You mean the two kids who were asking for candy, yes?",
  ui_story_5034_50340201_17_dialog_content = "Yeah, those two!",
  ui_story_5034_50340201_18_dialog_content = "They followed you into town, if I remember correctly.",
  ui_story_5034_50340201_19_dialog_content = "Wait, what? Why were they following me?",
  ui_story_5034_50340201_20_dialog_content = "After you left the church early this morning, those two took off shortly afterward, as well.",
  ui_story_5034_50340201_21_dialog_content = "I thought you were all traveling as a group... Does that mean you never saw them while you were in town?",
  ui_story_5034_50340201_22_dialog_content = "I didn't... I had no idea I was being followed. But I've already returned, so where could they be?",
  ui_story_5034_50340201_23_dialog_content = "Don't freak out, I'm sure they're wherever you last went.",
  ui_story_5034_50340201_24_dialog_content = "You're right! I should go back and look for them!",
  ui_story_5034_50340201_25_dialog_content = "I'll be right back, Corax! Keep an eye on the other kids for me, will you?",
  ui_story_5034_50340201_26_dialog_content = "Hey! Take this, too!",
  ui_story_5034_50340201_27_dialog_content = "Is this... <color=#FFB400>half a loaf of bread</color>?",
  ui_story_5034_50340201_28_dialog_content = "It's a little stale, but it'll have to suffice.",
  ui_story_5034_50340201_29_dialog_content = "If I let the last Caelestite in the world starve to death, I'll have to spend the rest of my life in Euphoria.",
  ui_story_5034_50340201_30_dialog_content = "Thank you, Corax... I'll savor every bite!",
  ui_story_5034_50340201_31_dialog_content = "(Schewe, Latan... I'm on my way! I just hope nothing bad has happened to them...)",
  ui_story_5034_50340202_1_dialog_content = "I didn't notice their presence at all...",
  ui_story_5034_50340202_2_dialog_content = "Don't tell me they're at the shop?",
  ui_story_5034_50340202_3_dialog_content = "Sunglasses for sale!",
  ui_story_5034_50340202_4_dialog_content = "The newest style, straight from Umbraton!",
  ui_story_5034_50340202_5_dialog_content = "Hmm? That voice sounds awfully familiar...",
  ui_story_5034_50340202_6_dialog_content = "Hey, mister? Can I interest you in a pair of sunglasses?",
  ui_story_5034_50340202_7_dialog_content = "They're all the rage in Umbraton!",
  ui_story_5034_50340202_8_dialog_content = "Huh?",
  ui_story_5034_50340202_9_dialog_content = "You sayin' I look like the kinda guy who needs sunglasses?!",
  ui_story_5034_50340202_10_dialog_content = "Is something wrong with the way my eyes look?!",
  ui_story_5034_50340202_11_dialog_content = "N-Not at all, sir! I didn't mean it like that...",
  ui_story_5034_50340202_12_dialog_content = "Heh... You know, seeing a pipsqueak like you working reminds me of myself when I was a kid.",
  ui_story_5034_50340202_13_dialog_content = "Alright kid, don't say I never did anything nice for ya. How much for the shades?",
  ui_story_5034_50340202_14_dialog_content = "Er... 6,000 Nightium a pair...",
  ui_story_5034_50340202_15_dialog_content = "Huh? You got guts, little girl... Tryin' to sucker people into buying sunglasses at that price is exactly the kind of thing I did as a kid!",
  ui_story_5034_50340202_16_dialog_content = "Unfortunately, you picked the wrong person to mess with today. Lemme give ya a taste of the real world...",
  ui_story_5034_50340202_17_dialog_content = "*Sobbing*",
  ui_story_5034_50340202_18_dialog_content = "Latan? Is that you?",
  ui_story_5034_50340202_19_dialog_content = "M-Mr. Navigator!",
  ui_story_5034_50340202_20_dialog_content = "*Sobbing* I'm over here...",
  ui_story_5034_50340202_21_dialog_content = "Lad, you better mind your own business!",
  ui_story_5034_50340202_22_dialog_content = "What if I won't?",
  ui_story_5034_50340202_23_dialog_content = "Pretty tough talk, for someone who's all alone...",
  ui_story_5034_50340202_24_dialog_content = "Who says I'm all alone?",
  ui_story_5034_50340202_25_dialog_content = "Over here, Corax! Pollux!",
  ui_story_5034_50340202_26_dialog_content = "What? That crazy lady is here too?!",
  ui_story_5034_50340202_27_dialog_content = "J-Just you wait, punk! I'll get you next time!",
  ui_story_5034_50340202_28_dialog_content = "PlayerName... Is Mr. Corax with you, too?",
  ui_story_5034_50340202_29_dialog_content = "Isn't he supposed to be watching over the other kids back at the church now?",
  ui_story_5034_50340202_30_dialog_content = "Sorry, Latan... I was bluffing to scare that guy away just now. Corax isn't here at all.",
  ui_story_5034_50340202_31_dialog_content = "If Mr. Corax was here, we wouldn't have to be so afraid of that <color=#FFB400>shopkeeper</color>...",
  ui_story_5034_50340202_32_dialog_content = "(\"Shopkeeper\"? Could she be talking about THAT shopkeeper?)",
  ui_story_5034_50340202_33_dialog_content = "Anyway, what's going on here, Latan? Why was that guy bothering you just now?",
  ui_story_5034_50340202_34_dialog_content = "And where's Schewe? I don't see him anywhere...",
  ui_story_5034_50340202_35_dialog_content = "I'll tell you what I'm doing later, Mr. Navigator. As for Schewe, he's inside the shop.",
  ui_story_5034_50340202_36_dialog_content = "The one where you bought the candy earlier today...",
  ui_story_5034_50340202_37_dialog_content = "I understand. I won't ask you why you followed me for the time being.",
  ui_story_5034_50340202_38_dialog_content = "Let's go find Schewe first, okay?",
  ui_story_5034_50340202_39_dialog_content = "Okay!",
  ui_story_5034_50340202_40_dialog_content = "<color=#e8d9bb>Clang!</color>",
  ui_story_5034_50340202_41_dialog_content = "Dropping my wares on the floor again, are we? I'll have to add that to your debt, too.",
  ui_story_5034_50340202_42_dialog_content = "Honestly... You came here to work for some money, but all you've done is rack up debts instead.",
  ui_story_5034_50340202_43_dialog_content = "If you can't even restock my shelves properly, I suggest you call it quits.",
  ui_story_5034_50340202_44_dialog_content = "Otherwise, you'll be fifty years old before you pay off your debts! Hahahaha!",
  ui_story_5034_50340202_45_dialog_content = "I... I can do it...",
  ui_story_5034_50340202_46_dialog_content = "<size=45>Ah!</size>",
  ui_story_5034_50340202_47_dialog_content = "<color=#e8d9bb>Clang-Clang!</color>",
  ui_story_5034_50340202_48_dialog_content = "Schewe!",
  ui_story_5034_50340202_49_dialog_content = "Are you okay?!",
  ui_story_5034_50340202_50_dialog_content = "I-I'm fine, Mr. Navigator... But I dropped another box, so the shopkeeper is going to add it to my debt again...",
  ui_story_5034_50340202_51_dialog_content = "Debt? What the heck is going on here?",
  ui_story_5034_50340202_52_dialog_content = "Well, well, well... If it isn't Mr. \"I'm Never Coming Back Again,\" back much sooner than expected.",
  ui_story_5034_50340202_53_dialog_content = "If you must know, this child owes me quite a lot of money for all of the trouble he's caused me.",
  ui_story_5034_50340202_54_dialog_content = "...",
  ui_story_5034_50340202_55_dialog_content = "If that's the case, then let's settle things from our previous \"transaction,\" shall we?",
  ui_story_5034_50340301_1_dialog_content = "Very well. Since you're a previous customer, I am more than happy to do so. Would you like for me to explain how this debt came to be?",
  ui_story_5034_50340301_2_dialog_content = "No thanks, I think I'll hear it from these two, instead.",
  ui_story_5034_50340301_3_dialog_content = "Schewe, Latan... Can you guys tell me exactly what's going on here? Don't worry, you're not in trouble.",
  ui_story_5034_50340301_4_option_content = "Can you tell me why you followed me?",
  ui_story_5034_50340301_5_dialog_content = "Sorry, Mr. Navigator... We just wanted to see where you were going to buy the candy.",
  ui_story_5034_50340301_6_dialog_content = "We followed you all the way here, and we saw how hard you worked for that one bag of candy.",
  ui_story_5034_50340301_7_option_content = "Can you tell me more about this \"debt\"?",
  ui_story_5034_50340301_8_dialog_content = "We wanted to do the same as you did, Mr. Navigator... We wanted to work hard to earn our candy, too.",
  ui_story_5034_50340301_9_dialog_content = "But work turned out to be much harder than we thought...",
  ui_story_5034_50340301_10_dialog_content = "I was put in charge of the shop's wares. My job was to bring stuff from the warehouse to the shop, and then organize it on the shelves.",
  ui_story_5034_50340301_11_dialog_content = "But the shopkeeper told me I wasn't allowed to drag the boxes on the ground, or else his wares would get damaged.",
  ui_story_5034_50340301_12_dialog_content = "I had no choice but to try and carry each box, but the stuff inside was so heavy...",
  ui_story_5034_50340301_13_dialog_content = "So every time when I dropped a box, he added it to my debt... He said it's to make up for my mistakes on the job.",
  ui_story_5034_50340301_14_dialog_content = "But I checked the stuff inside the boxes and they were all fine!",
  ui_story_5034_50340301_15_option_content = "What were you doing outside just now, Latan?",
  ui_story_5034_50340301_16_dialog_content = "The shopkeeper said that because I'm so cute, I should go outside and sell sunglasses to people as they passed by the shop.",
  ui_story_5034_50340301_17_dialog_content = "But nobody ever stops to listen to me...",
  ui_story_5034_50340301_18_dialog_content = "Except for that angry-looking guy. He's the only one who stopped to listen...",
  ui_story_5034_50340301_19_dialog_content = "But he kept getting angrier and angrier... and I was so scared...",
  ui_story_5034_50340301_19X1_dialog_content = "That's all. Sorry, PlayerName.",
  ui_story_5034_50340301_20_dialog_content = "I think I understand now. One last question...",
  ui_story_5034_50340301_21_option_content = "Why did you guys want to work for candy?",
  ui_story_5034_50340301_22_dialog_content = "If you were following me all along, then you must have known that I already bought the candy.",
  ui_story_5034_50340301_23_dialog_content = "Why did you want to work for even more?",
  ui_story_5034_50340301_24_dialog_content = "Well... After we saw how hard you worked just to buy us some candy...",
  ui_story_5034_50340301_25_dialog_content = "We didn't want to seem like a couple of selfish, bratty kids.",
  ui_story_5034_50340301_26_dialog_content = "So we decided to work hard so we could share our earnings with you and Pollux, because she always takes care of us.",
  ui_story_5034_50340301_27_dialog_content = "Pollux once told us the story of how a nun took care of her in the past.",
  ui_story_5034_50340301_28_dialog_content = "She said that one of the reasons she took over responsibility for the church and took in orphans like us... was to show her gratitude for that nun's kindness.",
  ui_story_5034_50340301_29_dialog_content = "I remember the look on her face when she told us that... It was so kind and warm.",
  ui_story_5034_50340301_30_dialog_content = "That's when I decided that I needed to be <color=#FFB400>someone who understands gratitude</color> as well.",
  ui_story_5034_50340301_31_dialog_content = "Someone grateful and warm, just like she is.",
  ui_story_5034_50340301_32_dialog_content = "I want to be like that, too... To make others feel warm, like Pollux and you.",
  ui_story_5034_50340301_33_dialog_content = "But it looks like all we've done is screw things up...",
  ui_story_5034_50340301_34_dialog_content = "I see.",
  ui_story_5034_50340301_35_dialog_content = "Playing such dirty tricks on innocent children like this...",
  ui_story_5034_50340301_36_dialog_content = "Is this how things fly in Euphoria?",
  ui_story_5034_50340301_37_dialog_content = "I was simply trying to teach them to take responsibility for the consequences of their choices.",
  ui_story_5034_50340301_38_dialog_content = "If you think about it, the debt they owe me is like tuition for my lesson.",
  ui_story_5034_50340301_39_dialog_content = "*Sobbing* PlayerName... I'm scared... I wanna go back to the church...",
  ui_story_5034_50340301_40_dialog_content = "(Forget it. It's pointless trying to reason with this shameless shopkeeper.)",
  ui_story_5034_50340301_41_dialog_content = "(I need to find a way to get these kids out of here first. Even if I wanna get back at that guy, I should discuss it with Corax first.)",
  ui_story_5034_50340301_42_dialog_content = "(I'm by myself right now, so it's best if I don't start anything.)",
  ui_story_5034_50340301_43_dialog_content = "These kids just wanted to buy two bags of candy. I'll pay for it.",
  ui_story_5034_50340301_44_dialog_content = "Just give them the candy and let them go. I'll settle the rest of their debts in their place.",
  ui_story_5034_50340301_45_dialog_content = "Have you already forgotten what happened this morning, my friend?",
  ui_story_5034_50340301_46_dialog_content = "Are you certain you can afford this candy?",
  ui_story_5034_50340301_47_dialog_content = "Heh, you've got some nerve, bringing that up. Of course I haven't forgotten.",
  ui_story_5034_50340301_48_dialog_content = "What's more, I found this printed on the bag!",
  ui_story_5034_50340301_49_dialog_content = "Not only are you selling counterfeit goods, you're also charging a hundred times over the suggested retail price! I still haven't settled the score with you over that!",
  ui_story_5034_50340301_50_dialog_content = "Hahaha! So what if you found out? I don't recall saying that my wares were genuine, do you?",
  ui_story_5034_50340301_51_dialog_content = "Besides, this is my shop, and I'm allowed to set the prices however I see fit.",
  ui_story_5034_50340301_52_dialog_content = "As for our transaction, you were willing to buy, and I was willing to sell... That's just how business works, don't you agree?",
  ui_story_5034_50340301_53_dialog_content = "Let's just forget about the candy, PlayerName...",
  ui_story_5034_50340301_54_dialog_content = "Oh, there's no going back on your word now. You asked for two bags, and now you have to pay for them.",
  ui_story_5034_50340301_55_dialog_content = "Stop scaring the kids already! I told you I was going to pay for them.",
  ui_story_5034_50340301_56_dialog_content = "We'll do it just like this morning. I'll work for both bags of candy.",
  ui_story_5034_50340301_57_dialog_content = "Very well, but you'll have to work twice as much as this morning.",
  ui_story_5034_50340301_58_dialog_content = "As for the children, they must stay here until you've finished your work.",
  ui_story_5034_50340301_59_dialog_content = "I'm not about to risk you lot running away when my head is turned.",
  ui_story_5034_50340301_60_dialog_content = "Let us help you, Mr. Navigator.",
  ui_story_5034_50340301_61_dialog_content = "I'll be fine, Schewe. You two can just sit over there and watch. I did this once already, so there's no need to worry.",
  ui_story_5034_50340301_62_dialog_content = "Oh, and here's the bag of candy I promised you earlier. You can snack on it while you wait for me, okay?",
  ui_story_5034_50340301_63_dialog_content = "Trust me, I'll be done before you know it, and we'll be back at the church in no time!",
  ui_story_5034_50340302_1_dialog_content = "(Thanks to my experience from the morning, I'm totally familiar with the work.)",
  ui_story_5034_50340302_2_dialog_content = "(As a result, I was able to do double the work in only half the time!)",
  ui_story_5034_50340302_3_dialog_content = "(Guess it's all in a day's work for me as Astra's Number One Errand Runner... Heheh...)",
  ui_story_5034_50340302_4_dialog_content = "Finished so soon? I suppose I was wrong to underestimate you, after all.",
  ui_story_5034_50340302_5_dialog_content = "Enough small talk. Just give the kids their candy and let them go.",
  ui_story_5034_50340302_6_dialog_content = "No need to be rude. Wait here, and I'll go fetch it.",
  ui_story_5034_50340302_7_dialog_content = "Oh dear, my condolences, friend.",
  ui_story_5034_50340302_8_dialog_content = "I just checked my shelves, and it looks like the candy's all sold out.",
  ui_story_5034_50340302_9_dialog_content = "What? Why didn't you tell us sooner? What was the point of all that work I did just now?!",
  ui_story_5034_50340302_10_dialog_content = "Again, there's no need to be rude. You worked for me twice in one day. Sounds like it was preordained by fate, if I do say so myself.",
  ui_story_5034_50340302_11_dialog_content = "Plus I would never dream of exploiting my workers like other mean-spirited employers.",
  ui_story_5034_50340302_12_dialog_content = "How about I just pay you in Nightium for those two bags of candy instead? Is that fair?",
  ui_story_5034_50340302_13_dialog_content = "(Well, I was able to get the kids some candy already...)",
  ui_story_5034_50340302_14_dialog_content = "(If I agree to the shopkeeper's suggestion, that means he owes me 6,000 Nightium.)",
  ui_story_5034_50340302_15_dialog_content = "(That should be more than enough for them to buy Pollux something else as a gift.)",
  ui_story_5034_50340302_16_dialog_content = "All right, I'll take your offer.",
  ui_story_5034_50340302_17_dialog_content = "Thank you for your understanding! Give me a moment, and I'll be back with your pay.",
  ui_story_5034_50340302_18_dialog_content = "Alright, here it is. Thank you again for your hard work!",
  ui_story_5034_50340302_19_dialog_content = "10, 20, 30... Wait, this is only 60 Nightium!",
  ui_story_5034_50340302_20_dialog_content = "What are you playing at here? Shouldn't it be 6,000 Nightium?",
  ui_story_5034_50340302_21_dialog_content = "There's no mistake, my friend. Each bag is worth 30 Nightium, so two bags would be 60 Nightium in total.",
  ui_story_5034_50340302_22_dialog_content = "Even those two children could easily do the math.",
  ui_story_5034_50340302_23_dialog_content = "But each bag was worth 3,000 Nightium, not 30!",
  ui_story_5034_50340302_24_dialog_content = "Ah... You forget things so easily, my friend.",
  ui_story_5034_50340302_25_dialog_content = "You were the one who told me each bag was only worth 30 Nightium, you know.",
  ui_story_5034_50340302_26_dialog_content = "See? In case you've forgotten, it's printed here on the bag.",
  ui_story_5034_50340302_27_dialog_content = "How can you be this shameless?!",
  ui_story_5034_50340302_28_dialog_content = "Hmph... I would think that after spending nearly an entire day here, you'd at least have some inkling of Euphoria's rules.",
  ui_story_5034_50340302_29_dialog_content = "Rules, rules, rules... I don't want to hear about \"Euphoria's rules\" anymore!",
  ui_story_5034_50340302_30_dialog_content = "You're always the one benefiting, so whose rules are these?!",
  ui_story_5034_50340302_31_dialog_content = "Hahaha! Are you finally beginning to understand, my young friend?",
  ui_story_5034_50340302_32_dialog_content = "Of course I'm always on the winning side... Because those without money or influence don't dictate the rules here.",
  ui_story_5034_50340302_33_dialog_content = "I'm done talking about this with you... Schewe, Latan, let's get out of here.",
  ui_story_5034_50340302_34_dialog_content = "Schewe?",
  ui_story_5034_50340302_35_dialog_content = "Latan?",
  ui_story_5034_50340302_36_dialog_content = "Where did you go?!",
  ui_story_5034_50340302_37_dialog_content = "And just where do you think you're going? There's still the matter of their debt, you know?",
  ui_story_5034_50340302_38_dialog_content = "Where are you hiding the kids? You better not do anything to them!",
  ui_story_5034_50340302_39_dialog_content = "What I decide to do with them depends entirely on you, my friend.",
  ui_story_5034_50340302_40_dialog_content = "You...",
  ui_story_5034_50340401_1_dialog_content = "What exactly do I need to do for you to let those two go?",
  ui_story_5034_50340401_2_dialog_content = "I'm but a simple merchant with simple demands. All I ask is that you pay off their debt.",
  ui_story_5034_50340401_3_dialog_content = "But you completely made up that debt!",
  ui_story_5034_50340401_4_dialog_content = "Well, if you're unwilling to pay it off, you can forget about leaving here with those two children.",
  ui_story_5034_50340401_5_dialog_content = "You bastard...!",
  ui_story_5034_50340401_6_dialog_content = "(Wait... Is he just getting to me, or do I sense Eclipsites nearby?)",
  ui_story_5034_50340401_7_dialog_content = "(There! The curtains behind the shopkeeper! That's where they're hiding!)",
  ui_story_5034_50340401_8_dialog_content = "(He shouldn't be so composed if there are Eclipsites showing up in his shop.)",
  ui_story_5034_50340401_9_dialog_content = "(Unless...)",
  ui_story_5034_50340401_10_dialog_content = "Are you... hiding Eclipsites in your shop?",
  ui_story_5034_50340401_11_dialog_content = "There's no use lying. I've already sensed their presence.",
  ui_story_5034_50340401_12_dialog_content = "Oh? So you're the Caelestite everyone talks about.",
  ui_story_5034_50340401_13_dialog_content = "Well, since you've already discovered that much, I suppose there's no harm in showing you.",
  ui_story_5034_50340401_14_dialog_content = "<color=#e8d9bb>Whoosh...</color>",
  ui_story_5034_50340401_15_dialog_content = "Y-You... How could you keep the kids cooped up with Eclipsites?!",
  ui_story_5034_50340401_16_dialog_content = "Waaaah!!",
  ui_story_5034_50340401_17_dialog_content = "Mr. Navigator! S-Save me...!",
  ui_story_5034_50340401_18_dialog_content = "H-He said that if we made any noise, he'd tell the Eclipsites to eat us...!",
  ui_story_5034_50340401_19_dialog_content = "That's enough, Latan. No more crying...",
  ui_story_5034_50340401_20_dialog_content = "We've already made enough trouble for Mr. Navigator...",
  ui_story_5034_50340401_21_dialog_content = "None of this is your guys' fault! It's my fault for making all those promises this morning.",
  ui_story_5034_50340401_22_dialog_content = "Don't worry! I'll make sure to get you home, safe and sound.",
  ui_story_5034_50340401_23_dialog_content = "Ah... Making even more promises, I see?",
  ui_story_5034_50340401_24_dialog_content = "You bastard... You're willing to throw away your humanity, all for a little money?!",
  ui_story_5034_50340401_25_dialog_content = "Hahahaha! You don't think it amusing to be talking about things like \"humanity\" and \"decency\" in Euphoria of all places?",
  ui_story_5034_50340401_26_dialog_content = "Besides, I've already told you what needs to be done to rescue them. I'm not completely heartless, you know?",
  ui_story_5034_50340401_27_dialog_content = "You can save them... or not. Your choice.",
  ui_story_5034_50340401_28_dialog_content = "(Of course I have to save them, but I can't keep letting this guy have the upper hand!)",
  ui_story_5034_50340401_29_dialog_content = "(The rope tying their hands together is attached to the Eclipsites' necks.)",
  ui_story_5034_50340401_30_dialog_content = "(If I want to rescue them, I'll have to undo the rope around the Eclipsites, too.)",
  ui_story_5034_50340401_31_dialog_content = "(Looks like I'll have to take a chance. Lend me some of your luck, Casta...)",
  ui_story_5034_50340401_32_dialog_content = "I've made my decision.",
  ui_story_5034_50340401_33_dialog_content = "So soon? Very good, now let's see if it's the right one.",
  ui_story_5034_50340401_34_dialog_content = "I've decided...",
  ui_story_5034_50340401_35_dialog_content = "To do this!",
  ui_story_5034_50340401_36_dialog_content = "Argh! You... Did you just throw a rock at me?! My eye...!",
  ui_story_5034_50340401_37_dialog_content = "You had it coming!",
  ui_story_5034_50340401_38_dialog_content = "(Good thing I didn't eat it. Corax wasn't joking when he said it was kind of stale.)",
  ui_story_5034_50340401_39_dialog_content = "(Never mind, there's no time to waste! I have to save the kids!)",
  ui_story_5034_50340401_40_dialog_content = "Mr. Navigator!",
  ui_story_5034_50340401_41_dialog_content = "I knew you would save us!",
  ui_story_5034_50340401_42_dialog_content = "Listen up, you two! As soon as I undo this rope, you need to run away as fast as you can!",
  ui_story_5034_50340401_43_dialog_content = "And don't turn back for any reason, got it?",
  ui_story_5034_50340401_44_dialog_content = "But what about you?",
  ui_story_5034_50340401_45_dialog_content = "He used the same rope to tie you up and the Eclipsites up. To untie you, I'll have to free the Eclipsites as well.",
  ui_story_5034_50340401_46_dialog_content = "Once I do, I'll get their attention and run in the opposite direction. Don't worry about me, I'll be fine!",
  ui_story_5034_50340401_47_dialog_content = "Mr. Navigator...",
  ui_story_5034_50340401_48_dialog_content = "Alright, we've got no time to lose. On the count of three, you guys run out as fast as you can, understand?",
  ui_story_5034_50340401_49_dialog_content = "One...",
  ui_story_5034_50340401_50_dialog_content = "Two...",
  ui_story_5034_50340401_51_dialog_content = "Three!",
  ui_story_5034_50340401_52_dialog_content = "<size=45>Run!</size>",
  ui_story_5034_50340402_1_dialog_content = "Grr... Graah...",
  ui_story_5034_50340402_2_dialog_content = "Graah...",
  ui_story_5034_50340402_3_dialog_content = "Urgh... I can't keep letting them chase me like this. I'm going to tire myself out eventually...",
  ui_story_5034_50340402_4_dialog_content = "I need to think of a plan to shake them off, and quick!",
  ui_story_5034_50340402_5_dialog_content = "Wait... If I remember correctly, that street up ahead is the one Corax and I took to enter the town!",
  ui_story_5034_50340402_6_dialog_content = "I think I have an idea!",
  ui_story_5034_50340402_7_dialog_content = "Hey, you oaf! You said <color=#FFB400>fate</color> keeps bringing us together, right? Well, right back at you!",
  ui_story_5034_50340402_8_dialog_content = "Graah!!",
  ui_story_5034_50340402_9_dialog_content = "Graaah!!",
  ui_story_5034_50340402_10_dialog_content = "You punk, are you hiding behind me with Eclipsites on your tail?",
  ui_story_5034_50340402_11_dialog_content = "The coast is clear. You can come out now.",
  ui_story_5034_50340402_12_dialog_content = "Wow, you really took them all out... You're not half bad, big guy!",
  ui_story_5034_50340402_13_dialog_content = "We meet again. Can't face me like a real man, so you resort to this kind of dirty trick?",
  ui_story_5034_50340402_14_dialog_content = "N-No, that's not it at all! Anyway, I've got somewhere to be right now, so... Bye!",
  ui_story_5034_50340402_15_dialog_content = "Can't thank you enough for your help, big guy! <color=#FFB400>Until fate brings us together again</color>!!",
  ui_story_5034_50340402_16_dialog_content = "Hey! Oi—!",
  ui_story_5034_50340402_17_dialog_content = "Call me PlayerName! Find me if you're ever in Eraveil, and I'll show you around!",
  ui_story_5034_50340402_18_dialog_content = "(Thank goodness I remembered that street was full of thugs. I was able to use them to get rid of those Eclipsites!)",
  ui_story_5034_50340402_19_dialog_content = "(I'm so glad everything went according to plan, or else I would've been in real trouble.)",
  ui_story_5034_50340402_20_dialog_content = "Strange... There doesn't seem to be anyone inside the shop.",
  ui_story_5034_50340402_21_dialog_content = "The shopkeeper and the rest of his Eclipsites are nowhere to be seen...",
  ui_story_5034_50340402_22_dialog_content = "Oh no... Could they be chasing after Schewe and Latan?!",
  ui_story_5034_50340402_23_dialog_content = "This is bad... I need to catch up to them and—",
  ui_story_5034_50340402_23X1_dialog_content = "<size=45>Ow!</size>",
  ui_story_5034_50340402_24_dialog_content = "Jeez, that hurt...",
  ui_story_5034_50340402_25_dialog_content = "Why do you look so frazzled? What happened?",
  ui_story_5034_50340402_26_dialog_content = "And why isn't anyone here?",
  ui_story_5034_50340402_27_dialog_content = "Casta...? Is it really you?",
  ui_story_5034_50340402_28_dialog_content = "Yeah, it's me. What happened here? And what's going on with you?",
  ui_story_5034_50340402_29_dialog_content = "Casta! I'm so glad you're here...",
  ui_story_5034_50340402_30_dialog_content = "We're kinda in trouble right now. I'll try to make it short...",
  ui_story_5034_50340402_31_dialog_content = "<color=#e8d9bb>After explaining everything to Casta...</color>",
  ui_story_5034_50340402_32_dialog_content = "I thought it was strange that the shop's door was wide open, which is why I stopped to take a look. I had no idea all that drama went down.",
  ui_story_5034_50340402_33_dialog_content = "I'm so sorry, Casta... I wasn't able to protect Schewe and Latan...",
  ui_story_5034_50340402_34_dialog_content = "Now's not the time to blame yourself, especially in your condition.",
  ui_story_5034_50340402_35_dialog_content = "Anyway, you're not on your own anymore. I'm here now.",
  ui_story_5034_50340402_36_dialog_content = "Whatever comes our way, we can figure out a solution together.",
  ui_story_5034_50340402_37_dialog_content = "We also know which direction they ran towards, so don't worry too much.",
  ui_story_5034_50340402_38_dialog_content = "This is Euphoria, after all. I won't let anything happen to those two.",
  ui_story_5034_50340402_39_dialog_content = "Thank you, Casta... I didn't know you could be so comforting.",
  ui_story_5034_50340402_40_dialog_content = "... I have no idea what you're talking about.",
  ui_story_5034_50340402_41_dialog_content = "Alright, let's get going! We have to find those two, no matter what.",
  ui_story_5034_50340402_42_dialog_content = "Lead the way.",
  ui_story_5034_50340501_1_dialog_content = "I can sense Eclipsites nearby... This street should be it.",
  ui_story_5034_50340501_2_dialog_content = "I really hope nothing bad happened to them, or else I—",
  ui_story_5034_50340501_3_dialog_content = "You said they came looking for work, so they could repay you and Pollux, right?",
  ui_story_5034_50340501_4_dialog_content = "Is that why you feel so responsible for their safety?",
  ui_story_5034_50340501_5_dialog_content = "Yes, but that's not the only reason... If I hadn't made a bunch of idealistic promises, none of this would've happened.",
  ui_story_5034_50340501_6_dialog_content = "My big mouth is what got them in this mess to begin with. And all because they wanted to work hard to buy me candy...",
  ui_story_5034_50340501_7_dialog_content = "That's just how those two are, to be honest.",
  ui_story_5034_50340501_8_dialog_content = "Over the last few years, Pollux and I have taken in at least seventy or eighty orphans here in Euphoria.",
  ui_story_5034_50340501_9_dialog_content = "And although most of them have very distinct personalities, those two kids stand out in a very unforgettable way.",
  ui_story_5034_50340501_10_option_content = "What do you mean by \"unforgettable\"?",
  ui_story_5034_50340501_11_dialog_content = "The bond between them is incredible.",
  ui_story_5034_50340501_12_dialog_content = "Latan changed Schewe for the better, and Schewe protects Latan at all costs. Only they can do these things for each other.",
  ui_story_5034_50340501_13_option_content = "I feel the same way.",
  ui_story_5034_50340501_14_dialog_content = "I knew you would understand.",
  ui_story_5034_50340501_15_dialog_content = "In any case, they're pretty special.",
  ui_story_5034_50340501_16_dialog_content = "If I remember correctly, Pollux rescued Schewe from an underground gambling den.",
  ui_story_5034_50340501_17_dialog_content = "When he first came to the church, he refused to lift his head or look anyone in the eyes.",
  ui_story_5034_50340501_18_dialog_content = "And he'd always speak to others in a very courteous and flattering manner, even to kids who were younger than him.",
  ui_story_5034_50340501_19_dialog_content = "Because in that gambling den, flattery was the only way to earn your meals and avoid punishment.",
  ui_story_5034_50340501_20_dialog_content = "He'd spent most of his life living in fear.",
  ui_story_5034_50340501_21_dialog_content = "Pollux and I tried everything, but we just couldn't get through the walls that he had built around himself.",
  ui_story_5034_50340501_22_dialog_content = "Then one day, Latan arrived at the church, and everything changed.",
  ui_story_5034_50340501_23_dialog_content = "<color=#e8d9bb>One Year Ago</color>",
  ui_story_5034_50340501_24_dialog_content = "*Sobbing*",
  ui_story_5034_50340501_25_dialog_content = "Wh-Why are you crying? Is it because I did a bad job wrapping your bandages?",
  ui_story_5034_50340501_26_dialog_content = "I'm sorry... I'm no good with this kind of thing...",
  ui_story_5034_50340501_27_dialog_content = "I've been practicing so much, but I still can't do it as well as Casta...",
  ui_story_5034_50340501_28_dialog_content = "It's all my fault... Please don't cry...",
  ui_story_5034_50340501_29_dialog_content = "*Sobbing* I... I'm not crying because of that...",
  ui_story_5034_50340501_30_dialog_content = "It's because of that guy with the scar on his face...",
  ui_story_5034_50340501_31_dialog_content = "He said he had to cut my hair off so he could stitch the wound on my head closed...",
  ui_story_5034_50340501_32_dialog_content = "A guy with a scar on his face? You mean Nekoyashiki?",
  ui_story_5034_50340501_33_dialog_content = "Then what happened? What did he do to you?",
  ui_story_5034_50340501_34_dialog_content = "Then... Then... He cut off my bangs and left me looking like this!",
  ui_story_5034_50340501_35_dialog_content = "*Sobbing* I look hideous now... Waaaaaah!",
  ui_story_5034_50340501_36_dialog_content = "Huh? Is that all? You look fine! In fact, if I take a closer look... *snickers*",
  ui_story_5034_50340501_37_dialog_content = "See! You're laughing, too! I knew it, I look like a freak! Waaaaaah!",
  ui_story_5034_50340501_38_dialog_content = "No, that's not it! If anything, you look even cuter now. Really!",
  ui_story_5034_50340501_39_dialog_content = "Y-You're lying... You're only saying that to make me feel better, aren't you?",
  ui_story_5034_50340501_40_dialog_content = "What?! But I'm not lying to you! That's how I really feel, I promise!",
  ui_story_5034_50340501_41_dialog_content = "*sniff* I'm sorry, but can I touch your hair for a second? If I do this, and then this...",
  ui_story_5034_50340501_42_dialog_content = "Wait here, I'll go get a mirror!",
  ui_story_5034_50340501_43_dialog_content = "Well? What do you think?",
  ui_story_5034_50340501_44_dialog_content = "*Sniffs*",
  ui_story_5034_50340501_44X1_dialog_content = "Well... I think it looks a little different...",
  ui_story_5034_50340501_45_dialog_content = "It's even sort of cute now...",
  ui_story_5034_50340501_45X1_dialog_content = "(T-There's actually no difference... I didn't actually anything...)",
  ui_story_5034_50340501_46_dialog_content = "Ah! W-Was it weird for me to say that? Will the others think I'm really snobby now?",
  ui_story_5034_50340501_47_dialog_content = "Although, I really do look cute, heehee...",
  ui_story_5034_50340501_48_dialog_content = "See? I told you I wasn't lying.",
  ui_story_5034_50340501_49_dialog_content = "My name is Latan. What's yours?",
  ui_story_5034_50340501_50_dialog_content = "I'm... Schewe.",
  ui_story_5034_50340501_51_dialog_content = "Sche-we!",
  ui_story_5034_50340501_52_dialog_content = "Yay! My new best friend's name is Sche-we!",
  ui_story_5034_50340501_53_dialog_content = "B-Best... friend?",
  ui_story_5034_50340501_54_dialog_content = "You mean you don't wanna be friends?",
  ui_story_5034_50340501_55_dialog_content = "N-No, of course I want to be friends!",
  ui_story_5034_50340501_56_dialog_content = "I'll be your best friend, and you can be my best friend as well! Okay?",
  ui_story_5034_50340501_57_dialog_content = "Okay!",
  ui_story_5034_50340501_58_dialog_content = "I thought those two just liked to play together. I had no idea they had that kind of past.",
  ui_story_5034_50340501_59_dialog_content = "Only someone as innocent and sincere as Latan could break down the walls surrounding Schewe's heart... It's truly a rare friendship.",
  ui_story_5034_50340501_60_dialog_content = "You're right, so Schewe won't let anything happen to Latan. He's a smart kid. Don't worry too much.",
  ui_story_5034_50340501_61_dialog_content = "Yeah... But still, I can't help but feel a little concerned. Also...",
  ui_story_5034_50340501_62_dialog_content = "Also?",
  ui_story_5034_50340501_63_dialog_content = "Watch your back! There's an Eclipsite behind us!",
  ui_story_5034_50340501_64_dialog_content = "Grr... Graah...",
  ui_story_5034_50340501_65_dialog_content = "Heh, watch this.",
  ui_story_5034_50340501_66_dialog_content = "Graaaah—",
  ui_story_5034_50340501_67_dialog_content = "Wait, I'm pretty sure this Eclipsite looks just like the one that was inside the shop.",
  ui_story_5034_50340501_68_dialog_content = "That means we're on the right track. Those two must've gone past here at some point.",
  ui_story_5034_50340501_69_dialog_content = "Casta, let's keep going!",
  ui_story_5034_50340501_70_dialog_content = "Roger that.",
  ui_story_5034_50340502_1_dialog_content = "I can sense Eclipsites nearby... Maybe they chased the kids down this street?",
  ui_story_5034_50340502_2_dialog_content = "Crap, not this thug-infested street again...",
  ui_story_5034_50340502_3_dialog_content = "Just relax, they won't lay a finger on you so long as I'm here.",
  ui_story_5034_50340502_4_dialog_content = "Well? Can you still sense any Eclipsites, or tell which way they went?",
  ui_story_5034_50340502_5_dialog_content = "I don't sense them anymore...",
  ui_story_5034_50340502_6_dialog_content = "But if they came through here, it's possible that they were wiped out by these street thugs, right?",
  ui_story_5034_50340502_7_dialog_content = "So what should we do now? That was our only lead...",
  ui_story_5034_50340502_8_dialog_content = "Don't worry, with all these people around, I'm sure someone must have seen those two.",
  ui_story_5034_50340502_9_dialog_content = "Let's split up and ask around.",
  ui_story_5034_50340502_10_dialog_content = "Okay...",
  ui_story_5034_50340502_11_dialog_content = "I know you still feel guilty, but right now our top priority is finding the kids.",
  ui_story_5034_50340502_12_dialog_content = "You're right. We need to hurry if we want to save them.",
  ui_story_5034_50340502_13_dialog_content = "I'll go ask around over there. Let's meet up here once we learn more.",
  ui_story_5034_50340502_14_dialog_content = "Sounds good.",
  ui_story_5034_50340502_15_dialog_content = "Hah? Not you, again!",
  ui_story_5034_50340502_16_dialog_content = "Geez, you're like an annoying fly that won't stop buzzing around my head. What are you doing here again?",
  ui_story_5034_50340502_17_dialog_content = "Ah, big guy! Thank goodness you're still here!",
  ui_story_5034_50340502_18_dialog_content = "Also, didn't I tell you my name? It's—",
  ui_story_5034_50340502_19_dialog_content = "PlayerName, right? I didn't forget, now hurry up and tell me what you want!",
  ui_story_5034_50340502_20_dialog_content = "Do you remember that little girl from earlier today? The one who tried to sell you a pair of sunglasses?",
  ui_story_5034_50340502_21_dialog_content = "Have you seen her around here?",
  ui_story_5034_50340502_22_dialog_content = "What, that little brat? Yeah, I saw her a while ago.",
  ui_story_5034_50340502_23_dialog_content = "She ran off in that direction with some other little boy.",
  ui_story_5034_50340502_24_dialog_content = "You're a lifesaver, big guy! You should think about opening an Odd Jobs here in Euphoria, you know?",
  ui_story_5034_50340502_25_dialog_content = "Gotta go now! Thanks again!",
  ui_story_5034_50340502_26_dialog_content = "What? Hey—",
  ui_story_5034_50340502_27_dialog_content = "He's gone. Damn punk...",
  ui_story_5034_50340502_28_dialog_content = [[
*Clears throat* 
<size=45>If you ever want to stay in Euphoria, I'll take you under my wing!</size>]],
  ui_story_5034_50340502_29_dialog_content = "<size=45>Sounds good to me!</size>",
  ui_story_5034_50340502_30_dialog_content = "<size=45>Except I get to call the shots!</size>",
  ui_story_5034_50340502_31_dialog_content = "Casta! I know which way they went!",
  ui_story_5034_50340502_32_dialog_content = "Great, then let's get going.",
  ui_story_5034_50340502_33_dialog_content = "Okay!",
  ui_story_5034_50340601_1_dialog_content = "Hmm? What's this...",
  ui_story_5034_50340601_2_dialog_content = "Wait, how did he get so far away already?",
  ui_story_5034_50340601_3_dialog_content = "It's not too late. I can still make it...",
  ui_story_5034_50340601_4_dialog_content = "Wait a minute!",
  ui_story_5034_50340601_5_dialog_content = "Latan, Schewe, I won't let anything happen to you guys...",
  ui_story_5034_50340601_6_dialog_content = "<size=45>I told you to wait!!</size>",
  ui_story_5034_50340601_7_dialog_content = "We don't have time to waste, Casta! If we don't hurry—",
  ui_story_5034_50340601_8_dialog_content = "Would you just calm down for a second? Take a look at this!",
  ui_story_5034_50340601_9_dialog_content = "This is... This is the candy I gave to them!",
  ui_story_5034_50340601_10_dialog_content = "And look! There's more over here!",
  ui_story_5034_50340601_11_dialog_content = "It looks like they were dropping pieces of candy as they ran. Maybe they were leaving a trail for us to follow?",
  ui_story_5034_50340601_12_dialog_content = "Well, it doesn't matter if they were doing it intentionally or not.",
  ui_story_5034_50340601_13_dialog_content = "As long as we follow the trail of candy, I'm sure we'll find them in no time.",
  ui_story_5034_50340601_14_dialog_content = "You're totally right. Sorry for losing my composure.",
  ui_story_5034_50340601_15_dialog_content = "It's a good thing you were here to notice the candy. Now let's hurry and follow the trail!",
  ui_story_5034_50340601_16_dialog_content = "Now hold on for just a second. We may not have to be in such a hurry, after all.",
  ui_story_5034_50340601_17_dialog_content = "If they chose to run down this street, then I can only think of one place they'd go.",
  ui_story_5034_50340601_18_dialog_content = "Are you saying you already know where they are?",
  ui_story_5034_50340601_19_dialog_content = "The church.",
  ui_story_5034_50340601_20_dialog_content = "One of the first things we teach the children is to come straight back to the church if they ever find themselves in trouble.",
  ui_story_5034_50340601_21_dialog_content = "But even so, there's a chance they ran into Eclipsites on the way. We can't relax just yet!",
  ui_story_5034_50340601_22_dialog_content = "I'm just as worried for their safety as you are, if not more so. But I don't want you to panic any more than you already have.",
  ui_story_5034_50340601_23_dialog_content = "Also... I trust her.",
  ui_story_5034_50340601_24_dialog_content = "As long as they make it near the church, I'm certain she won't let anything happen to them.",
  ui_story_5034_50340601_25_dialog_content = "Now let's get moving. We're going back to the <color=#FFB400>church</color>.",
  ui_story_5034_50340601_26_dialog_content = "Why is the church entrance surrounded by Eclipsites? Unless the shopkeeper chased them all the way here?",
  ui_story_5034_50340601_27_dialog_content = "Let's take them out, Casta! I'll guide you, and these Eclipsites won't stand a chance against us!",
  ui_story_5034_50340601_28_dialog_content = "I'd love to, but...",
  ui_story_5034_50340601_29_dialog_content = "<color=#e8d9bb>Bang! Bang!</color>",
  ui_story_5034_50340601_30_dialog_content = "I think this fight belongs to someone else now.",
  ui_story_5034_50340601_31_dialog_content = "Are these the monsters who chased you two back here?",
  ui_story_5034_50340601_32_dialog_content = "There's nothing to worry about anymore. Latan, Schewe, you're safe now.",
  ui_story_5034_50340601_33_dialog_content = "Pollux... I promise I won't run off like that again...",
  ui_story_5034_50340601_34_dialog_content = "I-It was all my fault...",
  ui_story_5034_50340601_35_dialog_content = "You've already apologized, haven't you? The most important thing is that you two are back, safe and sound.",
  ui_story_5034_50340601_36_dialog_content = "Come now... No more tears, okay?",
  ui_story_5034_50340601_37_dialog_content = "It's Pollux! And the kids, too! I'm so glad they're safe.",
  ui_story_5034_50340601_38_dialog_content = "Think you can finally stop worrying now?",
  ui_story_5034_50340601_39_dialog_content = "Here, this is for you.",
  ui_story_5034_50340601_40_dialog_content = "Casta... Did you pick up every piece of candy we saw on the way back?",
  ui_story_5034_50340601_41_dialog_content = "You seemed in too much of a hurry to mind them.",
  ui_story_5034_50340601_42_dialog_content = "Didn't you and the kids work hard for this candy? Here, now you can give it to them.",
  ui_story_5034_50340601_43_dialog_content = "Thank you! Thank you so much, Casta!",
  ui_story_5034_50340601_44_dialog_content = "If only you liked candy, too... That way, I could give you some as my way of saying thanks.",
  ui_story_5034_50340601_45_dialog_content = "Like I'd ever enjoy eating something as childish as candy.",
  ui_story_5034_50340601_46_dialog_content = "Damn it all! These brainless Eclipsites don't understand a word I say!",
  ui_story_5034_50340601_47_dialog_content = "How could they chase those two all the way back here?!",
  ui_story_5034_50340601_48_dialog_content = "I can handle losing money and merchandise, but if those two Raven's Blood women find out about this...",
  ui_story_5034_50340601_49_dialog_content = "Grr... Graah...",
  ui_story_5034_50340601_50_dialog_content = "G-Get away from me!",
  ui_story_5034_50340601_51_dialog_content = "Hey... It's the shopkeeper!",
  ui_story_5034_50340601_52_dialog_content = "How dare you show your face around here! I'm not letting you get away this time!",
  ui_story_5034_50340601_53_dialog_content = "Graaaah—",
  ui_story_5034_50340601_54_dialog_content = "Aaaaaahhh! Someone save me!!",
  ui_story_5034_50340601_55_dialog_content = "Save you? You're the one who brought all these Eclipsites here in the first place! You made your bed, now sleep in it!",
  ui_story_5034_50340601_56_dialog_content = "I... I was wrong! I'm sorry! I'm begging you, please help me!",
  ui_story_5034_50340601_57_dialog_content = "I'll do anything you want, just please don't let them eat me alive!",
  ui_story_5034_50340601_58_dialog_content = "Avenging the kids would feel a lot better if we did it ourselves, wouldn't you agree?",
  ui_story_5034_50340601_59_dialog_content = "You're absolutely right, Casta.",
  ui_story_5034_50340601_60_dialog_content = "I say we rescue him from the Eclipsites. That way, we can make him pay us back in full... with interest.",
  ui_story_5034_50340602_1_dialog_content = "Would anyone mind telling me what on earth is going on here?",
  ui_story_5034_50340602_2_dialog_content = "Sorry, Pollux. This was all my fault.",
  ui_story_5034_50340602_3_dialog_content = "You see, what happened was...",
  ui_story_5034_50340602_4_dialog_content = "<color=#e8d9bb>And so, I explained everything to Pollux from start to finish...</color>",
  ui_story_5034_50340602_5_dialog_content = "Alright, I understand now.",
  ui_story_5034_50340602_6_dialog_content = "We're no strangers to each other. I'm sure you're aware who's in charge here.",
  ui_story_5034_50340602_7_dialog_content = "P-Pollux... I swear, I didn't mean to lead those Eclipsites here! I...",
  ui_story_5034_50340602_8_dialog_content = "Unless... you thought a couple of Eclipsite minions would be enough to take me down?",
  ui_story_5034_50340602_9_dialog_content = "N-No! I swear that's not it!!",
  ui_story_5034_50340602_10_dialog_content = "It's just that I had no idea those two brats—I mean, those two valued customers were from your church...",
  ui_story_5034_50340602_11_dialog_content = "So what you're saying is that if they were just ordinary children, you would have had no problem cheating them or feeding them to Eclipsites? Is that it?",
  ui_story_5034_50340602_12_dialog_content = "I-I swear I'll never do it again! Please, just spare me this one time!",
  ui_story_5034_50340602_13_dialog_content = "I'll forget all about their debts!",
  ui_story_5034_50340602_14_dialog_content = "Oh, and their payment! Here, this is their payment for all their help! If it's not enough, I can always add more!",
  ui_story_5034_50340602_15_dialog_content = "Go ahead, Latan and Schewe. You two earned it, so it's yours to collect.",
  ui_story_5034_50340602_16_dialog_content = "I'll go, Latan. You wait here, okay?",
  ui_story_5034_50340602_17_dialog_content = "It's all here, Pollux! Not a single Nightium short!",
  ui_story_5034_50340602_18_dialog_content = "Ah, but surely it's not enough, yes? What else can I offer you? Candy? You can have it all!",
  ui_story_5034_50340602_19_dialog_content = "Please, just let me go back to my shop, and I promise I'll send someone to deliver it right to your doorstep!",
  ui_story_5034_50340602_20_dialog_content = "What makes you think we'll trust you after all this?",
  ui_story_5034_50340602_21_dialog_content = "And even if you do the right thing today, who's to say you won't just start swindling people again tomorrow?",
  ui_story_5034_50340602_22_dialog_content = "Ooh, what drama I've stumbled into. PlayerName has a point.",
  ui_story_5034_50340602_23_dialog_content = "Euphoria may be far off the beaten path, but even if all your wares are imported, your prices are still way too exorbitant, amounting to a monopoly.",
  ui_story_5034_50340602_24_dialog_content = "What's more, the goods you're charging an arm and a leg for aren't even the real deal.",
  ui_story_5034_50340602_25_dialog_content = "Nekoyashiki, quite hypocritical, aren't we?",
  ui_story_5034_50340602_26_dialog_content = "Isn't this how you make your money as well? The only difference is that you sell information and I sell merchandise.",
  ui_story_5034_50340602_27_dialog_content = "You don't feel guilty about any of this at all, do you?!",
  ui_story_5034_50340602_28_dialog_content = "D-Didn't I already agree to give you my money and candy in exchange for my safety?!",
  ui_story_5034_50340602_29_dialog_content = "What more do you want from me?!",
  ui_story_5034_50340602_30_dialog_content = "Well, since you're asking... I actually have an idea. If Pollux agrees, then we'll spare you.",
  ui_story_5034_50340602_31_dialog_content = "Let's hear your idea, then.",
  ui_story_5034_50340602_32_dialog_content = "We don't want any of your dirty money. You can keep it all for yourself.",
  ui_story_5034_50340602_33_dialog_content = "But you have to hand over your shop and let Nekoyashiki take over as its new owner.",
  ui_story_5034_50340602_34_dialog_content = "Since we can't guarantee that you'll change your ways, the least we can do is take away your shop and leave it with someone who won't rely on these kinds of tricks to make money.",
  ui_story_5034_50340602_35_dialog_content = "Besides, I'm sure you have enough money to get out of town and try your luck in Umbraton, right?",
  ui_story_5034_50340602_36_dialog_content = "I'm sure the merchants there would be more than happy to show you how to <color=#FFB400>do business in the right way</color>.",
  ui_story_5034_50340602_37_dialog_content = "But taking my shop is too much, don't you think...?",
  ui_story_5034_50340602_38_dialog_content = "I thought you said you were willing to do anything? Or are you going back on your word so quickly?",
  ui_story_5034_50340602_39_dialog_content = "Argh... Fine. The shop is all yours.",
  ui_story_5034_50340602_40_dialog_content = "Now can you please let me go?",
  ui_story_5034_50340602_41_dialog_content = "Don't ever let us catch you doing this sort of thing again, or you might not be so lucky next time. Understand?",
  ui_story_5034_50340602_42_dialog_content = "Oh, and do be careful on your way back. Some of your \"pets\" might still be roaming around out there.",
  ui_story_5034_50340602_43_dialog_content = "... Hmph.",
  ui_story_5034_50340602_44_dialog_content = "You seem peculiarly happy about PlayerName's conditions.",
  ui_story_5034_50340602_45_dialog_content = "You've been planning this, haven't you...",
  ui_story_5034_50340602_46_dialog_content = "Nothing gets past you at all.",
  ui_story_5034_50340602_47_dialog_content = "But I didn't expect the kids would get involved, too. That was my fault for being careless, and I'm sorry.",
  ui_story_5034_50340602_48_dialog_content = "I hurried back as soon as I heard what happened. Good thing he's pretty clever, or else the kids might've been in even more trouble.",
  ui_story_5034_50340602_49_dialog_content = "Where is he anyway?",
  ui_story_5034_50340603_1_dialog_content = "Mr. Navigator! I'm so glad the Eclipsites didn't gobble you up and spit out your bones!",
  ui_story_5034_50340603_2_dialog_content = "Of course they didn't... I know you don't mean anything else by it, but you should really choose your words more carefully, Latan.",
  ui_story_5034_50340603_3_dialog_content = "Anyway, come take a look at what I have here!",
  ui_story_5034_50340603_4_dialog_content = "It's the candy I left behind!",
  ui_story_5034_50340603_5_dialog_content = "I knew you'd find it, Mr. Navigator!",
  ui_story_5034_50340603_6_dialog_content = "You're the greatest, Mr. Navigator!",
  ui_story_5034_50340603_7_dialog_content = "It wasn't just me, you know? It was thanks to you guys and your quick thinking that I was able to follow your trail and find you.",
  ui_story_5034_50340603_8_dialog_content = "Still, I never expected you would pick them all up and give them back to us, Mr. Navigator...",
  ui_story_5034_50340603_9_dialog_content = "Well, they matter a lot to you, don't they? Here, take them.",
  ui_story_5034_50340603_10_dialog_content = "Also, Casta was the one who picked up the candy, not me. If anyone deserves your thanks, it's her.",
  ui_story_5034_50340603_11_dialog_content = "But Casta hates candy, or anything sweet for that matter... She only likes bitter stuff.",
  ui_story_5034_50340603_12_dialog_content = "Anyway, it's not like we forgot to get Casta a gift.",
  ui_story_5034_50340603_13_dialog_content = "Is that so? I still have to properly thank her for helping me out today.",
  ui_story_5034_50340603_14_dialog_content = "Except I have no idea where I'm supposed to find something bitter for her...",
  ui_story_5034_50340603_15_dialog_content = "So what did you two get her? Maybe I can borrow some inspiration?",
  ui_story_5034_50340603_16_dialog_content = "Uh...",
  ui_story_5034_50340603_17_dialog_content = "I guess it's okay to tell you, since you saved us today. But it's a surprise, so don't tell anyone!",
  ui_story_5034_50340603_18_dialog_content = "Our plan is to wait until she's not looking... and then surprise her with a big bear hug!",
  ui_story_5034_50340603_19_dialog_content = "Even though she always complains that it's too hot when we hug her...",
  ui_story_5034_50340603_20_dialog_content = "I've seen her smile to herself after every hug!",
  ui_story_5034_50340603_21_dialog_content = "If you want to thank her too, Mr. Navigator... why not give her a hug?",
  ui_story_5034_50340603_22_dialog_content = "Er... I think I'll just pretend I didn't hear anything.",
  ui_story_5034_50340603_23_dialog_content = "Do you think Pollux will like our candy too, Mr. Navigator?",
  ui_story_5034_50340603_24_dialog_content = "We caused so much trouble over some candy...",
  ui_story_5034_50340603_25_dialog_content = "Definitely. I'm sure she'll enjoy it very much.",
  ui_story_5034_50340603_26_dialog_content = "If you guys share your favorite things with her, she'll definitely appreciate the gesture.",
  ui_story_5034_50340603_27_dialog_content = "Besides, she would never get mad at you over what happened today.",
  ui_story_5034_50340603_28_dialog_content = "The most important thing for her, and for us, is that you're both safe and sound.",
  ui_story_5034_50340603_29_dialog_content = "Just think about it—wasn't she relieved when you two made it safely back to the church?",
  ui_story_5034_50340603_30_dialog_content = "If anything, you guys should be worried about me, and what she's going to do to me for causing all this trouble in the first place...",
  ui_story_5034_50340603_31_dialog_content = "Here, Mr. Navigator. Take half of my candy.",
  ui_story_5034_50340603_32_dialog_content = "Huh?",
  ui_story_5034_50340603_33_dialog_content = "If you give some to Pollux, there's no way she'll get mad at you, either!",
  ui_story_5034_50340603_34_dialog_content = "Th-Then take half of my candy too, Mr. Navigator!",
  ui_story_5034_50340603_35_dialog_content = "That's a thank-you gift for you, Mr. Navigator!",
  ui_story_5034_50340603_36_dialog_content = "Hahaha! Thank you so much, guys. I'll just take one piece from each of you, okay?",
  ui_story_5034_50340603_37_dialog_content = "I'll cherish the candy you gave me forever and ever!",
  ui_story_5034_50340603_38_dialog_content = "Schewe! Latan! PlayerName!",
  ui_story_5034_50340603_39_dialog_content = "Dinner is ready, so hurry up, or there won't be any left for you!",
  ui_story_5034_50340603_40_dialog_content = "Come on, you two. Let's go have a nice, hard-earned meal!",
  ui_story_5034_50340603_41_dialog_content = "Okay!"
}
return config
